{
  "title": "functions.expression.ImageInputSchema",
  "description": "Schema for an image input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected image.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "type": {
      "$ref": "functions.expression.ImageInputSchemaType"
    }
  }
}

{
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "anyOf": [
    {
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "enum": [
            "text"
          ]
        }
      }
    },
    {
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "enum": [
            "image_url"
          ]
        }
      }
    },
    {
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "enum": [
            "input_audio"
          ]
        }
      }
    },
    {
      "description": "Video input.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "input_video"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "video_url"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "enum": [
            "file"
          ]
        }
      }
    }
  ]
}

{
  "title": "agent.completions.message.InputAudio",
  "description": "Audio input for multimodal messages.",
  "type": "object",
  "properties": {
    "data": {
      "description": "Base64-encoded audio data.",
      "type": "string"
    },
    "format": {
      "description": "The audio format (e.g., \"wav\", \"mp3\").",
      "type": "string"
    }
  }
}

{
  "title": "agent.completions.message.ImageUrlDetail",
  "description": "Detail level for image processing.",
  "anyOf": [
    {
      "description": "Let the model decide the detail level.",
      "type": "string",
      "enum": [
        "auto"
      ]
    },
    {
      "description": "Low detail mode (faster, less tokens).",
      "type": "string",
      "enum": [
        "low"
      ]
    },
    {
      "description": "High detail mode (more accurate, more tokens).",
      "type": "string",
      "enum": [
        "high"
      ]
    }
  ]
}

{
  "title": "functions.expression.Expression",
  "description": "An expression that can be either JMESPath or Starlark.\n\nSerializes as `{\"$jmespath\": \"...\"}` or `{\"$starlark\": \"...\"}` in JSON.\n\n# Examples\n\nJMESPath:\n```json\n{\"$jmespath\": \"input.items[0].name\"}\n```\n\nStarlark:\n```json\n{\"$starlark\": \"input['items'][0]['name']\"}\n```",
  "anyOf": [
    {
      "description": "A JMESPath expression.",
      "type": "object",
      "properties": {
        "$jmespath": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "description": "A Starlark expression.",
      "type": "object",
      "properties": {
        "$starlark": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "description": "A predefined special expression variant.",
      "type": "object",
      "properties": {
        "$special": {
          "$ref": "functions.expression.Special"
        }
      },
      "additionalProperties": false
    }
  ]
}

{
  "title": "agent.completions.message.VideoUrl",
  "description": "A video URL for multimodal input.",
  "type": "object",
  "properties": {
    "url": {
      "description": "The URL of the video.",
      "type": "string"
    }
  }
}

{
  "title": "functions.expression.AudioInputSchema",
  "description": "Schema for an audio input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected audio.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "type": {
      "$ref": "functions.expression.AudioInputSchemaType"
    }
  }
}
